#!/usr/bin/env python3
import math, random, sys

# Physical constants (SI)
G = 6.67430e-11          # m^3 kg^-1 s^-2
c = 2.99792458e8        # m s^-1
M_sun = 1.98847e30      # kg

def geometric_mass(m_kg):
    """Convert a mass in kg to its geometric length (meters) in vacuo.
    In geometrized units, M (length) = G * m / c^2.
    """
    return G * m_kg / c**2

def random_spin(m_geom, max_a):
    """Return a random Kerr spin parameter a* in [0, max_a]."""
    return random.uniform(0.0, max_a)

def random_radius(m_geom, min_r, max_r):
    """Return a random Boyer‑Lindquist radius r (meters) in [min_r, max_r]."""
    return random.uniform(min_r, max_r)

def random_azimuth():
    """Return a random azimuthal angle θ (radians) in [0, π]."""
    return random.uniform(0.0, math.pi)

def random_polar(phi):
    """Return a random polar angle φ (radians) in [0, π/2]."""
    return random.uniform(0.0, math.pi/2)

def random_unit_vector():
    """Generate a random unit vector using spherical coordinates.
    Returns (r, theta, phi) where r=1, theta∈[0,π], φ∈[0,2π]."""
    theta = random.uniform(0.0, math.pi)
    phi = random.uniform(0.0, 2*math.pi)
    return (1.0, theta, phi)

def random_event(m_geom, max_a, min_r, max_r):
    """Generate a single randomized event (geometric mass, spin, radius, direction).
    Returns a dictionary with keys: 'mass_M', 'spin_a', 'radius_r', 'direction' (tuple).
    """
    mass_M = random.uniform(0.5, 5.0)          # solar‑mass scale
    a = random_spin(m_geom, max_a)            # dimensionless spin multiplier
    r = random_radius(m_geom, min_r, max_r)   # meters
    direction = random_unit_vector()
    return {
        'mass_M': mass_M,
        'spin_a': a,
        'radius_r': r,
        'direction': direction
    }

if __name__ == "__main__":
    # Example usage
    event = random_event(1.0, 0.99, 1.0, 10.0)
    print(event)

