#!/usr/bin/env python3
import numpy as np, json, os, sys, math, random

# Physical constants (SI)
G = 6.67430e-11          # m^3 kg^-1 s^-2
c = 2.99792458e8        # m s^-1
hbar = 1.054571817e-34  # J s
k_B = 1.380649e-23      # J K^-1
M_sun = 1.98847e30      # kg

def schwarzschild_radius(M):
    return 2 * G * M / c**2

def isco_radius(M):
    # Prograde ISCO radius for a non-rotating BH (a=0) from Bardeen et al.
    return 6 * G * M / c**2

def orbital_frequency(r, a=0.0):
    # Keplerian approximation for a circular orbit (a is unused here)
    return math.sqrt(G * M_sun / r**3)

def horizon_area(r):
    return 4 * math.pi * r**2

def hawking_temperature(M):
    return hbar * c**3 / (8 * math.pi * G * M * k_B)

def planck_length():
    return math.sqrt(hbar * G / c**3)

def rand_masses(n=1000):
    masses = []
    for _ in range(n):
        M = random.uniform(0.5, 50) * M_sun  # solar masses
        masses.append(M)
    return masses

def main():
    masses = rand_masses()
    results = []
    for M in masses:
        r_s = schwarzschild_radius(M)
        r_isco = isco_radius(M)
        v = orbital_frequency(r_isco)  # frequency at ISCO
        A = horizon_area(r_s)
        T = hawking_temperature(M)
        l_p = planck_length()
        results.append({
            "M_solar_masses": M / M_sun,
            "r_s_meters": r_s,
            "r_isco_meters": r_isco,
            "orbital_frequency_hz": v,
            "horizon_area_m2": A,
            "hawking_temperature_kelvin": T,
            "planck_length_meters": l_p
        })
    print(json.dumps(results, indent=2))

if __name__ == "__main__":
    main()

