import math, random, sys

# Physical constants (SI)
G = 6.67430e-11          # m^3 kg^-1 s^-2
c = 2.99792458e8        # m s^-1
M_sun = 1.98847e30      # kg

def chirp_mass(m1, m2):
    """Return the chirp mass M_c = (m1*m2)^{3/5} / (m1+m2)^{1/5}"""
    return (m1 * m2) ** (3.0/5.0) / (m1 + m2) ** (1.0/5.0)

def main():
    # Example: 30 M_sun binary
    m1 = m2 = 30 * M_sun
    M_c = chirp_mass(m1, m2)
    print(f"Chirp mass for a {m1/M_sun:.1f} M_sun binary: {M_c:.3e} kg")

if __name__ == "__main__":
    main()

#!/usr/bin/env python3
import os, json, sys
import numpy as np


def load_gwtc_catalog():
    """Load the GWTC catalog JSON and return the list of events.
    Expected environment variable: GWTC_CATALOG_PATH
    """
    path = os.getenv('GWTC_CATALOG_PATH')
    if not path:
        sys.stderr.write('Error: GWTC_CATALOG_PATH environment variable not set.\n')
        sys.exit(1)
    try:
        with open(path, 'r') as f:
            catalog = json.load(f)
    except Exception as e:
        sys.stderr.write(f'Error reading catalog: {e}\n')
        sys.exit(1)
    return catalog.get('events', [])

def main():
    events = load_gwtc_catalog()
    total = len(events)
    print(f"Total GW events in catalog: {total}")

if __name__ == "__main__":
    main()

#!/usr/bin/env python3
import numpy as np

# Physical constants (SI)
G = 6.67430e-11          # m^3 kg^-1 s^-2
c = 2.99792458e8        # m s^-1
M_sun = 1.98847e30      # kg

def schwarzschild_radius(M):
    """Schwarzschild radius r_s = 2GM/c^2"""
    return 2 * G * M / c**2

def photon_sphere_radius(M):
    """Photon sphere radius for a non-rotating BH: 1.5 * r_s"""
    return 1.5 * schwarzschild_radius(M)

def critical_impact_parameter(M):
    """Critical angular diameter θ_c = 6√3 GM/(c^2 D) (radians)"""
    return 6 * np.sqrt(3) * G * M / (c**2)

def angular_diameter(M, D):
    """Approximate angular diameter of the black hole (radians)"""
    return 2 * schwarzschild_radius(M) / D

def main():
    # Example: Sgr A* mass
    M = 4.31e6 * M_sun  # kg
    # Distance to Sgr A* (approximate)
    D = 8.102e3 * 3.085677581e16  # 8.102 kpc in meters

    theta_s = critical_impact_parameter(M)
    theta_r = angular_diameter(M, D)

    print(f"Critical impact parameter (radians): {theta_s:.3e}")
    print(f"Approximate angular diameter (radians): {theta_r:.3e}")
    print("Comparison: " + ("θ_r < θ_s" if theta_r < theta_s else "θ_r >= θ_s"))

if __name__ == "__main__":
    main()
